do $$declare s text;begin s:=pg_get_functiondef('prospecting.personalization_api(text,jsonb)'::regprocedure);s:=replace(s,$x$(coalesce(d->>'scope','top')='full' or s.lead_id is not null)$x$,$x$(coalesce(d->>'scope','top')='full' or (d->>'scope'='pilot' and exists(select 1 from prospecting.personalization_jobs pj where pj.lead_id=l.id)) or (coalesce(d->>'scope','top')='top' and s.lead_id is not null))$x$);execute s;end$$;
